from enum import Enum

from taf.fdsw.rc.interfaces.FDSW25A.diagnostics.exceptions import (
    UnsupportedAlarmFilterError,
)


class Flags(str, Enum):
    WITH_CANCELLED = "WithCancelled"


class Severities(str, Enum):
    CRITICAL = "Critical"
    MAJOR = "Major"
    MINOR = "Minor"
    WARNING = "Warning"


class AlarmFilters:

    def __init__(self):
        self._filters = {}

    def add_limit(self, limit):
        # limit is optional
        if limit is not None:
            self._validate_limit(limit)
            self._filters["limit"] = limit

    def add_offset(self, offset):
        # offset is optional
        if offset is not None:
            self._validate_offset(offset)
            self._filters["offset"] = offset

    def add_filters(self, filters):
        # filters is optional
        if filters is not None:
            self._validate_filter(filters)
            self._filters["filter"] = filters

    @property
    def filters(self):
        return self._filters

    @staticmethod
    def _validate_limit(limit):
        if not isinstance(limit, int):
            raise UnsupportedAlarmFilterError(
                f"Unsupported limit: {limit} {type(limit)}"
            )

    @staticmethod
    def _validate_offset(offset):
        if not isinstance(offset, int):
            raise UnsupportedAlarmFilterError(
                f"Unsupported offset: {offset} {type(offset)}"
            )

    @staticmethod
    def _validate_flags(flags):
        valid_flags = [flag.value for flag in Flags]
        for flag in flags:
            if flag not in valid_flags:
                raise UnsupportedAlarmFilterError(f"Unsupported flag: {flag}")

    @staticmethod
    def _validate_severity(severity):
        valid_severities = [severity.value for severity in Severities]
        for sev_type in severity:
            if sev_type not in valid_severities:
                raise UnsupportedAlarmFilterError(f"Unsupported severity: {sev_type}")

    def _validate_filter(self, filters):
        if not isinstance(filters, dict):
            raise UnsupportedAlarmFilterError(f"Unsupported filters: {filters}")

        self._validate_flags(filters.get("flags", []))
        self._validate_severity(filters.get("severity", []))
